import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import {
  InvoicesSkeleton,
  RevenueSkeleton,
  StatsSkeleton,
} from './DashboardSkeletons'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

function getDashboardData(): Promise<DashboardData> {
  return fetch('https://api.example.com/dashboard').then((res) => res.json())
}

async function DashboardStats({
  data,
}: {
  data: Promise<DashboardData>
}) {
  const dashboard = await data
  return (
    <CardStats
      totalRevenue={dashboard.totalRevenue}
      totalInvoices={dashboard.totalInvoices}
    />
  )
}

async function DashboardRevenue({
  data,
}: {
  data: Promise<DashboardData>
}) {
  const dashboard = await data
  return <RevenueChart revenue={dashboard.revenue} />
}

async function DashboardInvoices({
  data,
}: {
  data: Promise<DashboardData>
}) {
  const dashboard = await data
  return <LatestInvoices invoices={dashboard.invoices} />
}

export default function Page() {
  const dashboardData = getDashboardData()

  return (
    <main className="dashboard">
      <header className="dashboard-header">
        <div>
          <p className="eyebrow">Northstar Finance</p>
          <h1>Dashboard</h1>
          <p className="page-description">
            Track revenue and review your latest invoices.
          </p>
        </div>
      </header>

      <div className="dashboard-content">
        <section className="stats-region" aria-label="Key metrics">
          <Suspense fallback={<StatsSkeleton />}>
            <DashboardStats data={dashboardData} />
          </Suspense>
        </section>

        <div className="dashboard-panels">
          <Suspense fallback={<RevenueSkeleton />}>
            <DashboardRevenue data={dashboardData} />
          </Suspense>
          <Suspense fallback={<InvoicesSkeleton />}>
            <DashboardInvoices data={dashboardData} />
          </Suspense>
        </div>
      </div>
    </main>
  )
}
export function CardStats({
  totalRevenue,
  totalInvoices,
}: {
  totalRevenue: number
  totalInvoices: number
}) {
  return (
    <div className="stats-grid">
      <article className="metric-card">
        <p className="metric-label">Total revenue</p>
        <p className="metric-value">${totalRevenue.toLocaleString()}</p>
      </article>
      <article className="metric-card">
        <p className="metric-label">Total invoices</p>
        <p className="metric-value">{totalInvoices.toLocaleString()}</p>
      </article>
    </div>
  )
}
function SkeletonBlock({ className = '' }: { className?: string }) {
  return <span className={`skeleton ${className}`} />
}

