        <SkeletonBlock className="skeleton-label" />
        <SkeletonBlock className="skeleton-value" />
      </div>
      <div className="metric-card" aria-hidden="true">
        <SkeletonBlock className="skeleton-label" />
        <SkeletonBlock className="skeleton-value skeleton-value-short" />
      </div>
    </div>
  )
